function Read-TelemetryLast {
    $p = Get-TelemetryPaths
    if (-not $p -or -not [IO.File]::Exists($p.Last)) { return $null }
    try { return (ConvertFrom-JsonKeepOffset -Text (Read-SharedText -Path $p.Last)) } catch { return $null }
